mapper.select:
select r.id, r.order_id, r.user_id, r.provider_id, r.service_id, r.score, r.service_score, r.speed_score, r.quality_score, r.content, r.images, r.is_anonymous, r.reply, r.reply_time, r.status, r.create_time, case when r.is_anonymous = 1 then '匿名用户' else u.name end as userName, case when r.is_anonymous = 1 then null else u.avatar end as userAvatar, p.name as providerName, si.name as serviceName from review r left join `user` u on r.user_id = u.id left join provider p on r.provider_id = p.id left join service_item si on r.service_id = si.id
and r.service_id = #{serviceId}
and r.provider_id = #{providerId}
and r.user_id = #{userId}
and r.score = #{score}
and r.status = #{status}
order by r.create_time desc

select count(id) from review


        and provider_id = #{providerId}


        and service_id = #{serviceId}


        and status = #{status}


        and score = #{score}
